() => {
  const editor = document.querySelector('#editor');
  const scrollParent = editor.closest('[style*="overflow"]') || editor.parentElement;
  function getScrollInfo(el) {
    return el ? { scrollTop: el.scrollTop, scrollHeight: el.scrollHeight, clientHeight: el.clientHeight, tag: el.tagName, id: el.id } : null;
  }
  let el = editor;
  const chain = [];
  while (el) {
    chain.push(getScrollInfo(el));
    el = el.parentElement;
  }
  return chain;
}

